def countRatioSubarrays(nums, a, b):
    n = len(nums)
    count = 0

    # Fix the left end of the subarray
    for i in range(n):
        evens = 0
        odds = 0
        # Extend the right end one element at a time
        for j in range(i, n):
            if nums[j] % 2 == 0:
                evens += 1
            else:
                odds += 1
            # x / y <= a / b  <=>  x * b <= a * y  (all quantities positive, y > 0)
            if odds > 0 and evens * b <= a * odds:
                count += 1

    return count
